import{_ as e,c as o,o as a,a0 as r}from"./chunks/framework.DKRgXLPU.js";const i=JSON.parse('{"title":"Folhas de exercícios para jogos mentais","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/pt/exercise-worksheets.md","filePath":"public/downloads/pt/exercise-worksheets.md"}');const t=e({name:"public/downloads/pt/exercise-worksheets.md"},[["render",function(e,i,t,_,s,n){return a(),o("div",null,[...i[0]||(i[0]=[r('<h1 id="folhas-de-exercicios-para-jogos-mentais" tabindex="-1">Folhas de exercícios para jogos mentais <a class="header-anchor" href="#folhas-de-exercicios-para-jogos-mentais" aria-label="Permalink to &quot;Folhas de exercícios para jogos mentais&quot;">​</a></h1><p><strong>Academia Pétanque - Exercícios Práticos</strong></p><hr><h2 id="exercicio-1-reflexao-sobre-o-estado-de-fluxo" tabindex="-1">Exercício 1: Reflexão sobre o Estado de Fluxo <a class="header-anchor" href="#exercicio-1-reflexao-sobre-o-estado-de-fluxo" aria-label="Permalink to &quot;Exercício 1: Reflexão sobre o Estado de Fluxo&quot;">​</a></h2><h3 id="quando-voce-experimentou-o-estado-de-fluxo" tabindex="-1">Quando você experimentou o estado de fluxo? <a class="header-anchor" href="#quando-voce-experimentou-o-estado-de-fluxo" aria-label="Permalink to &quot;Quando você experimentou o estado de fluxo?&quot;">​</a></h3><p>Pense em uma ocasião em que você jogou sua melhor partida de petanca:</p><p><strong>Descreva a situação:</strong></p><ul><li>Que torneio/jogo era?</li><li>Quais eram as condições?</li><li>Com quem você estava jogando?</li></ul><hr><hr><p><strong>Como foi a sensação?</strong></p><ul><li>Qual era o seu estado mental?</li><li>Como você se sentiu em relação ao tempo?</li><li>Em que você estava pensando (ou não pensando)?</li></ul><hr><hr><p><strong>O que te ajudou a chegar lá?</strong></p><ul><li>O que você fez antes do jogo?</li><li>O que havia de diferente naquele dia?</li><li>Você consegue recriar alguma dessas condições?</li></ul><hr><hr><hr><h2 id="exercicio-2-inventario-do-critico-interior" tabindex="-1">Exercício 2: Inventário do Crítico Interior <a class="header-anchor" href="#exercicio-2-inventario-do-critico-interior" aria-label="Permalink to &quot;Exercício 2: Inventário do Crítico Interior&quot;">​</a></h2><h3 id="identifique-seu-critico-interno" tabindex="-1">Identifique seu crítico interno <a class="header-anchor" href="#identifique-seu-critico-interno" aria-label="Permalink to &quot;Identifique seu crítico interno&quot;">​</a></h3><p><strong>O que diz seu crítico interior?</strong></p><p>Liste de 3 a 5 pensamentos críticos comuns que você tem durante a competição:</p><ol><li><hr></li><li><hr></li><li><hr></li><li><hr></li><li><hr></li></ol><p><strong>Quando aparece?</strong></p><ul><li>Após erros? □</li><li>Antes das cenas importantes? □</li><li>Ao jogar contra adversários fortes? □</li><li>Quando os colegas de equipe estão assistindo? □</li><li>Outro: _______________________________________________</li></ul><hr><h2 id="exercicio-3-reformulando-a-pratica" tabindex="-1">Exercício 3: Reformulando a Prática <a class="header-anchor" href="#exercicio-3-reformulando-a-pratica" aria-label="Permalink to &quot;Exercício 3: Reformulando a Prática&quot;">​</a></h2><h3 id="transformar-critico-em-treinador" tabindex="-1">Transformar crítico em treinador <a class="header-anchor" href="#transformar-critico-em-treinador" aria-label="Permalink to &quot;Transformar crítico em treinador&quot;">​</a></h3><p><strong>Para cada pensamento do Crítico Interior, escreva uma reformulação do Orientador Interior:</strong></p><table tabindex="0"><thead><tr><th>Crítico Interior</th><th>Treinador Interior</th></tr></thead><tbody><tr><td>Exemplo: &quot;Eu sempre erro sob pressão&quot;</td><td>&quot;Já tive sucesso sob pressão antes, posso fazer isso de novo&quot;</td></tr><tr><td>1. _________________________</td><td>_________________________</td></tr><tr><td>2. _________________________</td><td>_________________________</td></tr><tr><td>3. _________________________</td><td>_________________________</td></tr></tbody></table><p><strong>Pratique dizer isso em voz alta</strong></p><hr><h2 id="exercicio-4-planejamento-da-rotina-pre-arremesso" tabindex="-1">Exercício 4: Planejamento da Rotina Pré-Arremesso <a class="header-anchor" href="#exercicio-4-planejamento-da-rotina-pre-arremesso" aria-label="Permalink to &quot;Exercício 4: Planejamento da Rotina Pré-Arremesso&quot;">​</a></h2><h3 id="crie-sua-rotina-pessoal" tabindex="-1">Crie sua rotina pessoal <a class="header-anchor" href="#crie-sua-rotina-pessoal" aria-label="Permalink to &quot;Crie sua rotina pessoal&quot;">​</a></h3><p>Crie uma rotina pré-injeção de 4 etapas que funcione para você:</p><p><strong>Etapa 1: Visualize</strong></p><ul><li>O que exatamente você vai visualizar?</li><li>Quanto tempo (2-3 segundos)?</li></ul><hr><p><strong>Passo 2: Respire</strong></p><ul><li>Uma respiração profunda ou três?</li><li>Existe algum padrão específico?</li></ul><hr><p><strong>Etapa 3: Âncora</strong></p><ul><li>Que âncora física você usará?</li><li>Toque na bola? Posição específica?</li></ul><hr><p><strong>Etapa 4: Executar</strong></p><ul><li>Qual é o seu sinal mental?</li><li>&quot;Confiança&quot; / &quot;Fluxo&quot; / &quot;Ir&quot;?</li></ul><hr><p><strong>Pratique esta rotina 10 vezes hoje</strong></p><hr><h2 id="exercicio-5-gatilhos-de-pressao" tabindex="-1">Exercício 5: Gatilhos de Pressão <a class="header-anchor" href="#exercicio-5-gatilhos-de-pressao" aria-label="Permalink to &quot;Exercício 5: Gatilhos de Pressão&quot;">​</a></h2><h3 id="identifique-seus-pontos-de-pressao" tabindex="-1">Identifique seus pontos de pressão <a class="header-anchor" href="#identifique-seus-pontos-de-pressao" aria-label="Permalink to &quot;Identifique seus pontos de pressão&quot;">​</a></h3><p><strong>Quais situações geram pressão para você?</strong></p><p>Classifique cada item de 1 (sem pressão) a 10 (pressão extrema):</p><ul><li>Jogando contra adversários fortes: ___/10</li><li>Jogos importantes do torneio: ___/10</li><li>Placar empatado, último lance: ___/10</li><li>Após cometer um erro: ___/10</li><li>Quando os colegas de equipe estão assistindo: ___/10</li><li>Quando estou jogando mal: ___/10</li><li>Outros: _________________________ ___/10</li></ul><p><strong>Para o seu gatilho de maior classificação:</strong></p><p>Que sensações físicas você percebe?</p><hr><p>Que pensamentos surgem?</p><hr><p>Qual técnica você usará?</p><ul><li>[ ] Reinicialização de 3 respirações</li><li>[ ] Rotina pré-filmagem</li><li>[ ] Reenquadramento</li><li>[ ] Outro: _____________________</li></ul><hr><h2 id="exercicio-6-pratica-de-troca-de-modos" tabindex="-1">Exercício 6: Prática de Troca de Modos <a class="header-anchor" href="#exercicio-6-pratica-de-troca-de-modos" aria-label="Permalink to &quot;Exercício 6: Prática de Troca de Modos&quot;">​</a></h2><h3 id="planejamento-versus-execucao" tabindex="-1">Planejamento versus Execução <a class="header-anchor" href="#planejamento-versus-execucao" aria-label="Permalink to &quot;Planejamento versus Execução&quot;">​</a></h3><p><strong>Pratique a troca:</strong></p><p><strong>Fase de Planejamento (Antes da foto):</strong></p><ul><li>O que preciso analisar?</li><li>Qual é a minha estratégia?</li><li>Qual foto vou escolher?</li></ul><p><strong>Fase de Execução (Durante a filmagem):</strong></p><ul><li>Limpe sua mente</li><li>Confie no seu corpo.</li><li>Deixe acontecer</li></ul><p><strong>Exercício prático:</strong></p><p>Faça 5 arremessos de treino. Para cada um:</p><ol><li>Dedique 10 segundos ao modo de planejamento (analisar, decidir).</li><li>Respire fundo 3 vezes para mudar de modo.</li><li>Executar em modo de fluxo (sem pensar)</li></ol><p><strong>Reflexão:</strong></p><ul><li>Você conseguiu sentir a diferença entre os modos?</li><li>O interruptor estava livre?</li><li>Qual modo é mais difícil para você?</li></ul><hr><hr><hr><h2 id="exercicio-7-plano-de-pratica-semanal" tabindex="-1">Exercício 7: Plano de Prática Semanal <a class="header-anchor" href="#exercicio-7-plano-de-pratica-semanal" aria-label="Permalink to &quot;Exercício 7: Plano de Prática Semanal&quot;">​</a></h2><h3 id="destaque-desta-semana" tabindex="-1">Destaque desta semana <a class="header-anchor" href="#destaque-desta-semana" aria-label="Permalink to &quot;Destaque desta semana&quot;">​</a></h3><p><strong>Escolha UMA técnica para praticar:</strong></p><ul><li>[ ] Reiniciar com 3 respirações após cada erro</li><li>[ ] Rotina pré-arremesso em cada lançamento</li><li>[ ] Reformule um pensamento do Crítico Interior por sessão</li><li>[ ] Troca para o modo de prática</li></ul><p><strong>Prática diária:</strong></p><table tabindex="0"><thead><tr><th>Dia</th><th>Atividade Prática</th><th>Duração</th><th>Observações</th></tr></thead><tbody><tr><td>Seg</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Terça</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Qua</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Qui</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sex</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sábado</td><td>________________</td><td>___min</td><td>________________</td></tr><tr><td>Sol</td><td>________________</td><td>___min</td><td>________________</td></tr></tbody></table><hr><h2 id="exercicio-8-acompanhamento-do-progresso" tabindex="-1">Exercício 8: Acompanhamento do progresso <a class="header-anchor" href="#exercicio-8-acompanhamento-do-progresso" aria-label="Permalink to &quot;Exercício 8: Acompanhamento do progresso&quot;">​</a></h2><h3 id="reflexao-do-final-de-semana" tabindex="-1">Reflexão do final de semana <a class="header-anchor" href="#reflexao-do-final-de-semana" aria-label="Permalink to &quot;Reflexão do final de semana&quot;">​</a></h3><p><strong>O que você praticou esta semana?</strong></p><hr><p><strong>O que você notou?</strong></p><hr><hr><p><strong>O que funcionou bem?</strong></p><hr><hr><p><strong>Qual foi o desafio?</strong></p><hr><hr><p><strong>O que você vai continuar fazendo na próxima semana?</strong></p><hr><hr><p><strong>O que você vai ajustar?</strong></p><hr><hr><hr><h2 id="proximos-passos" tabindex="-1">Próximos passos <a class="header-anchor" href="#proximos-passos" aria-label="Permalink to &quot;Próximos passos&quot;">​</a></h2><h3 id="continue-seu-desenvolvimento" tabindex="-1">Continue seu desenvolvimento <a class="header-anchor" href="#continue-seu-desenvolvimento" aria-label="Permalink to &quot;Continue seu desenvolvimento&quot;">​</a></h3><p><strong>Recursos em carreau.app:</strong></p><ul><li>Modelo de metas - Estruture seu desenvolvimento a longo prazo</li><li>Modelo de diário - Acompanhe o progresso diário</li><li>A Zona - Uma análise profunda dos estados de fluxo</li><li>Força Mental - Gestão Avançada da Pressão</li></ul><p><strong>Continue praticando:</strong></p><ul><li>As habilidades mentais precisam de treinamento constante.</li><li>Comece pequeno e vá aumentando gradualmente.</li><li>Acompanhe seu progresso</li><li>Comemore as melhorias</li></ul><hr><p><em>Pétanque Academy - Desenvolvimento de Jogadores de Elite</em><em>carreau.app</em></p>',113)])])}]]);export{i as __pageData,t as default};
